// Unit tests for the resource tables generated by linux/tools/rcgen.py (the
// 7zFM set), MyLoadString(), CLang language files and the locale mapping.

#include <QDir>
#include <QFile>
#include <QRegularExpression>
#include <QTemporaryDir>
#include <QTest>

#include <stdlib.h>

#include "Win32Compat.h"

#include "../../../CPP/Common/Lang.h"
#include "../../../CPP/Windows/DLL.h"
