#include "../../../CPP/7zip/UI/FileManager/CopyDialogRes.h"
#include "../../../CPP/7zip/UI/FileManager/SettingsPageRes.h"
#include "../../../CPP/7zip/UI/GUI/CompressDialogRes.h"
#include "../../../CPP/7zip/UI/Explorer/resource.h"

